// Queries for the users domain.
// Static queries live here. The ones built at run time stay hand-written: the
// partial UPDATE (repository.go), and the members list, suspended-accounts list
// and sign-in summary with their filters and counts (list.go, suspension.go,
// signins.go).
// CreateWithCredential inserts the user and (optionally) their password credential
// in one tx; both halves are static and run as sqlc queries on the same pgx.Tx.
// InsertUser is the user-row half of CreateWithCredential; the cross-context
// password credential is inserted by InsertPasswordCredential on the same tx.
func (q *Queries) InsertUser(ctx context.Context, arg InsertUserParams) (InsertUserRow, error) {
	row := q.db.QueryRow(ctx, insertUser,
		arg.OrganizationID,
		arg.Email,
		arg.Phone,
		arg.DisplayName,
		arg.Metadata,
	)
	var i InsertUserRow
	err := row.Scan(
		&i.ID,
		&i.OrganizationID,
		&i.Email,
		&i.EmailVerifiedAt,
		&i.Phone,
		&i.PhoneVerifiedAt,
		&i.DisplayName,
		&i.Status,
		&i.Metadata,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}

